import{z as d,x as B,o as t,c as A,q as l,j as o,D as E,d as r,s as i,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"译码器与编码器","description":"","frontmatter":{"title":"译码器与编码器","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/decoder-encoder.md","filePath":"cs/decoder-encoder.md","lastUpdated":1791063341000}'),p={name:"cs/decoder-encoder.md"};function c(m,a,u,h,C,D){const n=B("Mermaid");return t(),A("div",null,[a[2]||(a[2]=l('<h1 id="译码器与编码器" tabindex="-1">译码器与编码器 <a class="header-anchor" href="#译码器与编码器" aria-label="Permalink to &quot;译码器与编码器&quot;">​</a></h1><div class="epigraph"><p>译码器把二进制编号点亮唯一一条选择线；编码器走反向，把「哪一根热」收成编号。</p><footer>—— 据 Harris and Harris, Digital Design and Computer Architecture 整理</footer></div><p>上一课<a href="/cs/mux-select">多路选择器</a>内部其实已经用了「选择线的最小项」。本课不重写 \\(2^k\\):1 的式子，也不从存储阵列另起。缺口是：这个「点亮一根线」的块要独立出来——寄存器堆写使能、后课存储器字线、指令操作码展开，都叫<strong>译码器</strong>；反向则是编码器。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>MUX 的数据端是宽总线。若只需 \\(2^n\\) 根独热线（每次恰好一根为 1），那是 \\(n\\) 到 \\(2^n\\) 译码。缺口因此不是新的选择语义，而是输出形态：独热，而不是多路数据里挑值。编码器假定输入已是独热（或带优先级），输出二进制编号。两者都是组合，延迟随 \\(n\\) 增加。</p><p><span class="marginnote">数字实例：3 到 8 译码器有 3 根输入、8 根输出，任一时刻恰有一根输出为 1——输入 101（十进制 5）时只有 5 号线亮。输入 \\(n\\) 线性增长、输出 \\(2^n\\) 指数爆炸，所以 16 位地址对 65536 条字线的译码必须分层搭，不能一层面糊。</span></p><p>不完全指定：未使用的操作码可以当 \\(X\\)，或必须导向非法指令——与<a href="/cs/dont-care-hazard">险象课</a>的 \\(X\\) 政策相接，本课不重讲毛刺。</p><h3 id="独热不是「好几根可以同时亮」" tabindex="-1">独热不是「好几根可以同时亮」 <a class="header-anchor" href="#独热不是「好几根可以同时亮」" aria-label="Permalink to &quot;独热不是「好几根可以同时亮」&quot;">​</a></h3><p>二进制计数器的输出不是独热。若干使能同时有效是另一编码，要用优先级编码器或报错。把译码器输出直接线或，会变回多驱动问题；应在设计上保证互斥，或用 MUX。</p><p><span class="marginnote">常见误区：初学者容易把独热当成「可以好几根一起亮」的宽松状态。独热的合同恰恰是任何时刻至多一根为 1；多根同时热说明上游出错或用了别的编码，普通编码器此时输出无意义——要么换优先编码器，要么先在设计上保证互斥。</span></p><p><span class="marginnote">Harris 将 decoder 与 MUX 对照：MUX 是「译码后与数据与」。存储器阵列的行译码就是本课块加大驱动。编码器用于中断源编号，后课入口再接。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>\\(n\\):\\(2^n\\) 译码：输出 \\(i\\) 为选择值等于 \\(i\\) 的最小项。使能端把全体输出与上。优先编码器：输入可多 1，输出最高优先编号，并给 valid。</p>',13)),(t(),o(s,null,{default:E(()=>[i(n,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20BIN%5B%22%E4%BA%8C%E8%BF%9B%E5%88%B6%E7%BC%96%E5%8F%B7%22%5D%20--%3E%20DEC%5B%22%E7%8B%AC%E7%83%AD%E5%AD%97%E7%BA%BF%22%5D%0A%20%20DEC%20--%3E%20ENC%5B%22%E7%BC%96%E5%8F%B7%E6%94%B6%E5%9B%9E%22%5D%0A%20%20DEC%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E5%8A%A0%E6%B3%95%E5%99%A8%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,[r("后课寄存器堆：写地址经译码得到 32 根写使能之一。SRAM 行译码同构，只是扇出到整行。指令译码把 "),e("code",null,"opcode"),r("/"),e("code",null,"funct"),r(" 变成控制独热或变成后课真值表的输入——那张表是控制课，本课只提供组合展开。")],-1)),a[5]||(a[5]=e("p",null,"编码器压缩「哪一个请求」。无请求时 valid=0，避免把 0 号与「没有」混名。",-1)),a[6]||(a[6]=e("p",null,[e("span",{class:"marginnote"},"直觉类比：译码器像酒店前台把房间号变成「只亮一盏灯」——几号房有客，哪盏灯亮。优先编码器像一排呼叫铃：同时响时只报最高优先的那间，valid 灯则负责区分「有人按了 0 号铃」和「根本没人按」。")],-1)),(t(),o(s,null,{default:E(()=>[i(n,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20R%5B%22%E8%AF%B7%E6%B1%82%E7%BA%BF%201010%EF%BC%9A%E4%B8%A4%E8%B7%AF%E5%90%8C%E6%97%B6%E8%A6%81%22%5D%20--%3E%20PE%5B%22%E4%BC%98%E5%85%88%E7%BC%96%E7%A0%81%E5%99%A8%EF%BC%9A%E5%8F%96%E6%9C%80%E9%AB%98%E4%BC%98%E5%85%88%202%20%E5%8F%B7%22%5D%0A%20%20PE%20--%3E%20OUT%5B%22%E8%BE%93%E5%87%BA%E4%BA%8C%E8%BF%9B%E5%88%B6%2010%EF%BC%8Cvalid%3D1%22%5D%0A%20%20NONE%5B%22%E8%AF%B7%E6%B1%82%E7%BA%BF%200000%EF%BC%9A%E6%97%A0%E4%BA%BA%E8%AF%B7%E6%B1%82%22%5D%20--%3E%20PE2%5B%22%E4%BC%98%E5%85%88%E7%BC%96%E7%A0%81%E5%99%A8%22%5D%0A%20%20PE2%20--%3E%20OUT0%5B%22%E8%BE%93%E5%87%BA%2000%20%E4%BD%86%20valid%3D0%EF%BC%9A%E4%B8%8D%E6%98%AF%200%20%E5%8F%B7%E8%AF%B7%E6%B1%82%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=l('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲模拟译码、不把 PLA 与译码器当成两种完全不同的数学——PLA 是可编程的与或平面。时序「扫描」用计数器驱动译码是后课计数器。</p><p>后课默认：地址到字线用译码器；独热与二进制的转换用编/译码组合块。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>译码：二进制 → 独热；编码：独热（或优先）→ 二进制。</li><li>MUX = 译码与数据相与再或。</li><li>写口、字线、操作码展开都是译码器实例。</li><li>出处：Harris and Harris。</li></ul>',5))])}const _=d(p,[["render",c]]);export{F as __pageData,_ as default};
